const j = $json || {};
const requested = Number(j.requested || j['Batch size'] || 60);
return [{
  json: {
    batch_id: j.batch_id || 'RB-' + String(Date.now()).slice(-6),
    topic: j.topic || j.Topic || 'Industrial suppliers in Ontario',
    requested: requested > 0 ? requested : 60,
    source_quality: j.source_quality || j['Minimum source quality'] || 'company website, dated in the last 90 days',
    started_at: new Date().toISOString(),
    status: 'received',
  },
}];

// Deterministic seed: 52 clean rows plus 8 deliberate defects, all stamped with this batch id.
const batch = $('Prepare Batch').first().json.batch_id;
const CLEAN = 52;
const CATS = ['manufacturing', 'logistics', 'retail', 'services', 'technology'];
const today = new Date().toISOString().slice(0, 10);
const rows = [];
for (let i = 1; i <= CLEAN; i++) {
  const n = String(i).padStart(3, '0');
  rows.push({
    batch_id: batch,
    id: 'R-' + n,
    company: 'Rowan ' + CATS[i % CATS.length].replace(/^./, (c) => c.toUpperCase()) + ' ' + n,
    contact_name: 'Alex Morgan',
    email: 'alex.morgan@rowan' + n + '.co',
    category: CATS[i % CATS.length],
    source_url: 'https://rowan' + n + '.co/about',
    source_date: today,
  });
}
rows.push({ batch_id: batch, id: 'R-053', company: '', contact_name: 'Priya Shah', email: 'priya@example.com', category: 'retail', source_url: 'https://northline.co/team', source_date: today });
