const REQUIRED = ['id', 'company', 'contact_name', 'email', 'category', 'source_url', 'source_date'];
const ALLOWED_CATEGORIES = ['manufacturing', 'logistics', 'retail', 'services', 'technology'];
const DEAD_DOMAINS = ['dead.example', 'placeholder.test', 'baddomain.invalid'];
const PLACEHOLDER_EMAILS = ['example.com', 'test.com', 'invalid.com'];
const STALE_DAYS = 90;
const domainOf = (url) => { const m = String(url || '').match(/^https?:\/\/([^\/?#]+)/i); return m ? m[1].toLowerCase() : ''; };
const rows = $input.all().map((i) => i.json);
const seen = new Set();
const out = [];
const checked = new Date().toISOString();
for (const r of rows) {
  const defects = [];
  for (const f of REQUIRED) if (!String(r[f] === undefined || r[f] === null ? '' : r[f]).trim()) defects.push('missing_' + f);
  const url = String(r.source_url || '');
  if (url && !/^https?:\/\//i.test(url)) defects.push('invalid_url');
  const domain = domainOf(url);
  if (DEAD_DOMAINS.some((d) => domain === d || domain.endsWith('.' + d))) defects.push('dead_source');
  const email = String(r.email || '').toLowerCase();
  if (PLACEHOLDER_EMAILS.includes(email.split('@')[1] || '')) defects.push('placeholder_email');
  const name = String(r.contact_name || '').trim();
  if (name && !/^[A-Z][a-z]+ [A-Z][a-z]+$/.test(name)) defects.push('name_mismatch');
  const category = String(r.category || '').trim();
  if (category && !ALLOWED_CATEGORIES.includes(category)) defects.push('bad_category');
  const date = new Date(r.source_date || 0);
  if (!isNaN(date.getTime()) && Date.now() - date.getTime() > STALE_DAYS * 864e5) defects.push('stale_source');
  const id = String(r.id || '').trim();
  if (seen.has(id)) defects.push('duplicate_id');
  else seen.add(id);
  out.push({ json: { ...r, status: defects.length ? 'exception' : 'verified', defects, checked_at: checked } });
}
return out;

// A pending decision row is still written for the audit trail; the phone approval id
// lets the decision webhook append the signed outcome against the same exception.
const batch = $('Prepare Batch').first().json.batch_id;
return $input.all().map((i) => ({
  json: {
    batch_id: batch,
    exception_id: i.json.id,
    decision: 'pending',
    reviewer: '',
    decided_at: '',
    note: 'awaiting reviewer',
    shotty_approval_id: i.json.shotty_approval_id || '',
  },
}));

// Keep the exception row and attach the Shotty approval id.
const rows = $('Append Exceptions').all();
const responses = $input.all();
return rows.map((row, i) => ({
  json: {
    ...row.json,
    shotty_approval_id: responses[i] && responses[i].json ? responses[i].json.id : null,
    shotty_status: responses[i] && responses[i].json ? responses[i].json.status : 'unknown',
  },
}));
